@block GroundPlanar begin
    @ports p::Power{Planar}, [frame = "world"]
    @equations p.f ~ [0.0, 0.0, 0.0]
    @causality p => (:flow_out, :fixed)
end

@block PlanarBodyDriven begin
    @ports p::Power{Planar}, [frame = "world"]
    @inputs w::Vec{6}
    @parameters begin
        m::Real = 1.0, [unit = "kg", min = 0, description = "Mass"]
        J::Real = 0.02, [unit = "kg*m^2", min = 0, description = "Yaw inertia"]
    end
    @variables P::Vec{3} = [0.0, 0.0, 0.0], [state = :prefer]
    @equations begin
        # m and J are valid. The spatial wrench's roll/pitch components have no matching
        # planar inertia, so the assembled mass matrix is singular (E109).
        p.e[1] ~ w[1]
        p.e[2] ~ w[4]
        p.e[3] ~ w[5]
        for k in 1:3
            ddt(P[k]) ~ p.e[k]
        end
        p.f[1] ~ P[1] / J
        p.f[2] ~ P[2] / m
        p.f[3] ~ P[3] / m
    end
    @causality p => :flow_out
end

@block SpatialWrenchDrive begin
    @outputs w::Vec{6}
    @parameters begin
        tau::Vec{3} = [0.0, 0.0, 0.0], [unit = "N*m", description = "Torque components"]
        f::Vec{3} = [0.0, 0.0, 0.0], [unit = "N", description = "Force components"]
    end
    @equations w ~ [tau[1], tau[2], tau[3], f[1], f[2], f[3]]
end
